// 봉의고등학교 (강원 춘천시) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by scripts/campuses/bongui/build-package.mjs
// from OSM way/476499591 + Copernicus GLO-30: every school building destructible (grammar models, floors estimated where OSM has none),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, BONGUI_PLACEMENTS, BONGUI_BUILDING_BASE, BONGUI_HEIGHT_GRIDS, BONGUI_HEIGHT_RANGE_M, BONGUI_ENV_IDS, BONGUI_DISPLAY, BONGUI_START_FRAME, BONGUI_OVERVIEW_AZIMUTH, BONGUI_CAMERA, BONGUI_PROVENANCE } from './data.js';
import { BONGUI_FOOTPRINTS } from './footprints.js';
import { BONGUI_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(BONGUI_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/bongui/${file}`, import.meta.url).href;
const HAZE = BONGUI_DISPLAY.haze, FADE = BONGUI_DISPLAY.fade;

export const BONGUI = Object.freeze({
  id: 'bongui',
  meta: Object.freeze({ school: '봉의고등학교', campus: '춘천', short: '봉의고', modelNoun: '봉의고' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: BONGUI_PLACEMENTS,
  approvedCount: BONGUI_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600 ? { min: [-12,-11,-18], max: [40,-3,-8], azimuth: 0.25, elevationDegrees: 25 } : { min: [-38,-1,-28], max: [38,12,-11], azimuth: 0.05 }; }, overviewAzimuth: BONGUI_OVERVIEW_AZIMUTH }),
  camera: BONGUI_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: BONGUI_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: BONGUI_HEIGHT_GRIDS, buildingBase: BONGUI_BUILDING_BASE, source: BONGUI_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: BONGUI_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: BONGUI_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'scripts/campuses/bongui/build-package.mjs baked ground' }),
  }),
  protected: Object.freeze({ models: BONGUI_PROTECTED }),
  hazardTape: Object.freeze({ footprints: BONGUI_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: BONGUI_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default BONGUI;
